/* eslint-disable jsx-a11y/no-redundant-roles -- Preserve markerless list semantics in Safari. */
import { useState, type ReactNode } from "react";
import { MessageSquare, Search } from "lucide-react";
import type { ChatConversation } from "@/types/chat";
import { useChatConversationFilter } from "@/hooks/chat/useChatConversationFilter";
import { ChatSkeleton } from "./ChatSkeleton";
import { ConversationItem } from "./ConversationItem";

type Props = {
  actions?: ReactNode;
  updatesPaused?: boolean;
  activeConversationId: number | null;
  conversations: ChatConversation[];
  drafts?: Record<number, string>;
  isThreadOpen: boolean;
  loading: boolean;
  onSelect: (id: number) => void;
};

export function ChatConversationList({
  actions,
  updatesPaused = false,
  activeConversationId,
  conversations,
  drafts = {},
  isThreadOpen,
  loading,
  onSelect,
}: Props) {
  const { filteredConversations, query, setQuery } =
    useChatConversationFilter(conversations);

  const [unreadOnly, setUnreadOnly] = useState(false);
  const unreadCount = conversations.filter(
    (item) => item.unread_count > 0,
  ).length;
  // Keep the selected thread in view after acknowledging its unread messages.
  const visibleConversations = filteredConversations.filter(
    (item) =>
      !unreadOnly || item.unread_count > 0 || item.id === activeConversationId,
  );

  return (
    <aside
      aria-label="Lista de conversas"
      className={`min-h-0 flex-col overflow-hidden border-r border-border bg-white lg:flex ${
        isThreadOpen ? "hidden" : "flex"
      }`}
    >
      <div className="shrink-0 border-b border-border">
        <div className="flex items-start gap-3 bg-brand-blue px-5 py-5 text-white">
          <span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl border border-white/20 bg-white/10">
            <MessageSquare
              className="h-5 w-5"
              strokeWidth={1.75}
              aria-hidden="true"
            />
          </span>
          <div className="min-w-0">
            <h2 className="mb-0 text-lg font-bold leading-6 tracking-tight">
              Mensagens
            </h2>
            <p className="mt-0.5 text-sm leading-5">
              {conversations.length}{" "}
              {conversations.length === 1 ? "conversa" : "conversas"}
              {updatesPaused && <span className="mt-1 block text-xs">Atualizações pausadas</span>}
            </p>
          </div>
          {actions}
        </div>
        <div className="space-y-3 bg-white p-4">
          <label className="relative block">
            <span className="sr-only">Buscar conversa</span>
            <Search
              className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
              aria-hidden="true"
            />
            <input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Buscar conversa"
              className="h-11 w-full rounded-xl border border-input bg-slate-50 pl-9 pr-3 text-base text-foreground outline-none transition-colors duration-200 placeholder:text-muted-foreground focus:border-ring focus:bg-white focus-visible:ring-2 focus-visible:ring-brand-blue"
            />
          </label>
          <div
            className="grid grid-cols-2 gap-1 rounded-xl border border-border bg-slate-100 p-1"
            role="group"
            aria-label="Filtrar conversas"
          >
            {[
              { label: "Todas", value: false, count: conversations.length },
              { label: "Não lidas", value: true, count: unreadCount },
            ].map((filter) => (
              <button
                key={filter.label}
                type="button"
                aria-pressed={unreadOnly === filter.value}
                onClick={() => setUnreadOnly(filter.value)}
                className={`inline-flex min-h-11 min-w-0 items-center justify-center gap-1.5 rounded-lg px-2 text-sm font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue ${unreadOnly === filter.value ? "bg-white text-brand-blue-ink shadow-sm" : "text-muted-foreground hover:bg-white/70"}`}
              >
                {filter.label}
                <span
                  className={`grid min-h-5 min-w-5 place-items-center rounded-md px-1 text-xs ${unreadOnly === filter.value ? "bg-brand-blue/10 text-brand-blue-ink" : "bg-slate-200 text-muted-foreground"}`}
                >
                  {filter.count}
                </span>
              </button>
            ))}
          </div>
        </div>
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain bg-white px-2 py-2">
        {loading && <ChatSkeleton />}
        {!loading && conversations.length === 0 && (
          <p className="p-4 text-sm leading-6 text-muted-foreground">
            Nenhuma conversa iniciada ainda.
          </p>
        )}
        {!loading &&
          conversations.length > 0 &&
          visibleConversations.length === 0 && (
            <p className="p-4 text-sm leading-6 text-muted-foreground">
              {unreadOnly && !query.trim()
                ? "Nenhuma conversa não lida por aqui."
                : "Nenhuma conversa encontrada."}
            </p>
          )}
        <ul role="list" aria-label="Conversas">
          {visibleConversations.map((conversation) => (
            <li key={conversation.id}>
              <ConversationItem
                conversation={conversation}
                draft={drafts[conversation.id]}
                isActive={activeConversationId === conversation.id}
                onSelect={onSelect}
              />
            </li>
          ))}
        </ul>
      </div>
    </aside>
  );
}

import {
  Check,
  CheckCheck,
  Download,
  ExternalLink,
  FileText,
  Image as ImageIcon,
  Flag,
} from "lucide-react";
import type { ChatMessage } from "@/types/chat";
import { ChatAvatar } from "./ChatAvatar";
import {
  extractFirstUrl,
  formatChatTime,
  formatFileSize,
  formatUrlHost,
} from "./chatUtils";

type Props = {
  isMine: boolean;
  message: ChatMessage;
  onReport: (messageId: number) => void;
  showMeta: boolean;
  showSender: boolean;
};

function DeliveryIcon({ message }: { message: ChatMessage }) {
  if (message.read_at || message.delivery_status === "read") {
    return (
      <CheckCheck
        className="h-3.5 w-3.5"
        role="img"
        aria-label="Mensagem lida"
      />
    );
  }
  if (message.delivery_status === "delivered") {
    return (
      <CheckCheck
        className="h-3.5 w-3.5"
        role="img"
        aria-label="Mensagem entregue"
      />
    );
  }
  return (
    <Check className="h-3.5 w-3.5" role="img" aria-label="Mensagem enviada" />
  );
}

export function MessageBubble({
  isMine,
  message,
  onReport,
  showMeta,
  showSender,
}: Props) {
  const firstUrl = extractFirstUrl(message.body);
  const attachments = message.attachments ?? [];

  return (
    <article
      className={`flex motion-safe:animate-[chat-message-in_180ms_ease-out] ${
        isMine ? "justify-end" : "justify-start"
      }`}
    >
      <div
        className={`flex max-w-[82%] gap-2 ${isMine ? "flex-row-reverse" : ""}`}
      >
        {!isMine && (
          <span
            className={`mt-0.5 ${showSender ? "opacity-100" : "opacity-0"}`}
          >
            <ChatAvatar peer={message.sender} size="sm" />
          </span>
        )}
        <div className="min-w-0">
          <div
            className={`rounded-2xl px-4 py-3 text-base leading-6 shadow-sm sm:text-sm sm:leading-5 ${
              isMine
                ? "rounded-br-sm bg-brand-blue text-white shadow-[0_2px_8px_#0750781a]"
                : "rounded-bl-sm border border-brand-blue/15 bg-white text-foreground"
            }`}
          >
            {attachments.map((attachment) =>
              attachment.kind === "image" ? (
                <div
                  key={attachment.id}
                  className={`mb-3 overflow-hidden rounded-xl border ${
                    isMine
                      ? "border-white/15 bg-white/10"
                      : "border-border bg-slate-50"
                  }`}
                >
                  <img
                    src={attachment.url}
                    alt={attachment.name}
                    className="max-h-72 w-full object-cover"
                  />
                  <div className="flex items-center justify-between gap-3 px-3 py-2 text-xs">
                    <span className="min-w-0 break-words font-medium">
                      {attachment.name}
                    </span>
                    <span className="shrink-0 opacity-70">
                      {formatFileSize(attachment.size)}
                    </span>
                  </div>
                </div>
              ) : (
                <div
                  key={attachment.id}
                  className={`mb-3 flex items-center gap-3 rounded-xl border px-3 py-3 text-sm ${
                    isMine
                      ? "border-white/15 bg-white/10"
                      : "border-border bg-slate-50"
                  }`}
                >
                  <span className="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-white/80 text-brand-blue-ink">
                    <FileText aria-hidden="true" className="h-5 w-5" />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block break-words font-semibold">
                      {attachment.name}
                    </span>
                    <span className="block text-xs opacity-70">
                      {formatFileSize(attachment.size)}
                    </span>
                  </span>
                  <Download
                    aria-hidden="true"
                    className="h-4 w-4 shrink-0 opacity-70"
                  />
                </div>
              ),
            )}
            {attachments.length === 0 && message.message_type === "image" && (
              <div
                className={`mb-3 overflow-hidden rounded-xl border ${
                  isMine
                    ? "border-white/15 bg-white/10"
                    : "border-border bg-slate-50"
                }`}
              >
                <div className="flex aspect-[16/9] items-center justify-center bg-gradient-to-br from-brand-blue/10 via-white/20 to-slate-200">
                  <ImageIcon
                    aria-hidden="true"
                    className="h-8 w-8 opacity-70"
                  />
                </div>
              </div>
            )}
            {message.body && (
              <p className="whitespace-pre-wrap break-words leading-5">
                {message.body}
              </p>
            )}
            {firstUrl && (
              <div
                className={`mt-3 flex items-center gap-3 rounded-xl border px-3 py-2 text-xs ${
                  isMine
                    ? "border-white/15 bg-white/5 text-white"
                    : "border-border bg-slate-50 text-muted-foreground"
                }`}
              >
                <span className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-white/80 text-brand-blue-ink">
                  <ExternalLink aria-hidden="true" className="h-4 w-4" />
                </span>
                <span className="min-w-0">
                  <span className="block break-words font-semibold">
                    {formatUrlHost(firstUrl)}
                  </span>
                  <span className="block break-words opacity-70">
                    {firstUrl}
                  </span>
                </span>
              </div>
            )}
            {showMeta && (
              <div
                className={`mt-1 flex items-center justify-end gap-2 text-xs ${
                  isMine ? "text-white" : "text-muted-foreground"
                }`}
              >
                {!isMine && (
                  <button
                    type="button"
                    onClick={() => onReport(message.id)}
                    className="inline-flex items-center gap-1 rounded px-1 py-0.5 text-muted-foreground transition hover:bg-status-danger-soft hover:text-status-danger focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-300"
                    aria-label="Denunciar mensagem inadequada"
                  >
                    <Flag aria-hidden="true" className="h-3 w-3" />
                    Denunciar
                  </button>
                )}
                <span className="inline-flex items-center gap-1">
                  {formatChatTime(message.created_at)}
                  {isMine && <DeliveryIcon message={message} />}
                </span>
              </div>
            )}
          </div>
        </div>
      </div>
    </article>
  );
}

type Props = {
  peerName?: string;
};

export function TypingIndicator({ peerName = "Contato" }: Props) {
  return (
    <div
      className="flex justify-start motion-safe:animate-[chat-message-in_180ms_ease-out]"
      role="status"
      aria-live="polite"
    >
      <div className="flex items-center gap-2 rounded-2xl rounded-tl-sm border border-border bg-white px-4 py-3 text-sm text-muted-foreground shadow-sm">
        <span>{peerName} está digitando</span>
        <span className="flex gap-1" aria-hidden="true">
          <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-slate-400 [animation-delay:-0.2s]" />
          <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-slate-400 [animation-delay:-0.1s]" />
          <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-slate-400" />
        </span>
      </div>
    </div>
  );
}

import { Link } from "react-router-dom";
import { CreditCard } from "lucide-react";
import { Button } from "@/components/ui/button";
import type { OrderDetailData } from "./orderDetailTypes";
import { orderStatusInfo } from "./orderDetailUtils";

interface OrderDetailHeaderProps {
  order: OrderDetailData;
  resumeState?: Record<string, unknown>;
}

export function OrderDetailHeader({
  order,
  resumeState,
}: OrderDetailHeaderProps) {
  const meta = orderStatusInfo[order.status] || orderStatusInfo.pending;
  const StatusIcon = meta.icon;

  return (
    <div className="mt-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
      <div>
        <p className="text-xs font-bold uppercase tracking-[0.18em] text-brand-blue-ink">
          Detalhes da compra
        </p>
        <div className="mt-1.5">
          <h1 className="text-3xl font-bold leading-tight text-foreground">
            Pedido #{order.id}
          </h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Realizado em {new Date(order.created_at).toLocaleString("pt-BR")}
          </p>
        </div>
      </div>
      <div className="space-y-2">
        <div
          className={`${meta.className} sm:min-w-[220px] rounded-lg px-5 py-3.5 shadow-sm`}
          role="status"
          aria-label={`Status do pedido: ${meta.label}`}
        >
          <p className="text-[11px] font-bold uppercase tracking-[0.18em] opacity-70">
            Status do pedido
          </p>
          <div className="mt-1.5 flex items-center gap-2.5">
            <StatusIcon className="h-5 w-5" />
            <span className="text-base font-bold">{meta.label}</span>
          </div>
        </div>
        {order.payment_provider === "development" && (
          <Button asChild variant="outline" className="w-full">
            <Link to={`/payment/development/${order.id}`}>
              Controlar pagamento simulado
            </Link>
          </Button>
        )}
        {resumeState &&
          order.status === "pending" &&
          order.cancellation_status !== "pending" && (
            <Button
              asChild
              className="w-full bg-brand-orange text-white hover:bg-brand-orange-hover"
            >
              <Link to="/checkout" state={resumeState}>
                <CreditCard className="mr-2 h-4 w-4" />
                Finalizar pagamento
              </Link>
            </Button>
          )}
      </div>
    </div>
  );
}

import { ReceiptText } from "lucide-react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import type { OrderDetailData } from "./orderDetailTypes";
import { formatOrderCurrency, orderPaymentLabels } from "./orderDetailUtils";

interface OrderSummaryCardProps {
  order: OrderDetailData;
  totals: { products: number; shipping: number };
}

export function OrderSummaryCard({ order, totals }: OrderSummaryCardProps) {
  return (
    <aside>
      <Card className="lg:sticky lg:top-24 border-border shadow-sm">
        <CardHeader>
          <h2 className="flex items-center gap-2 text-2xl font-semibold">
            <ReceiptText className="h-5 w-5 text-brand-blue-ink" />
            Resumo do pedido
          </h2>
        </CardHeader>
        <CardContent className="space-y-4">
          <SummaryRow
            label="Produtos"
            value={formatOrderCurrency(totals.products)}
          />
          <SummaryRow
            label="Frete"
            value={formatOrderCurrency(totals.shipping)}
          />
          {Number(order.discount_amount || 0) > 0 && (
            <SummaryRow
              label={`Cupom ${order.coupon_code || ""}`.trim()}
              value={`-${formatOrderCurrency(Number(order.discount_amount || 0))}`}
            />
          )}
          <SummaryRow
            label="Pagamento"
            value={
              order.payment_method
                ? orderPaymentLabels[order.payment_method] ||
                  order.payment_method
                : "Não informado"
            }
          />
          {order.payment_status && (
            <SummaryRow
              label="Status no provedor"
              value={order.payment_status}
            />
          )}
          {order.paid_at && (
            <SummaryRow
              label="Pago em"
              value={new Date(order.paid_at).toLocaleString("pt-BR")}
            />
          )}
          {order.cancellation_status && (
            <div
              role="status"
              className="rounded-lg border border-border bg-slate-50 p-3 text-sm text-muted-foreground"
            >
              <p className="font-semibold">
                {order.cancellation_status === "pending"
                  ? "Cancelamento em conciliação"
                  : "Cancelamento conciliado"}
              </p>
              <p className="mt-1">
                {order.cancellation_status === "pending"
                  ? "O pedido está cancelado. Estamos verificando o cancelamento das cobranças e os estornos necessários."
                  : order.payment_status === "refunded"
                    ? "O reembolso foi confirmado pelo provedor de pagamento."
                    : "As cobranças deste pedido foram encerradas."}
              </p>
            </div>
          )}
          <Separator />
          <div className="flex items-end justify-between">
            <span className="font-semibold text-foreground">Total</span>
            <span className="text-2xl font-bold text-brand-blue-ink">
              {formatOrderCurrency(order.total_amount)}
            </span>
          </div>
          <p className="rounded-lg bg-slate-50 p-3 text-xs leading-5 text-muted-foreground">
            Última atualização em{" "}
            {new Date(order.updated_at).toLocaleString("pt-BR")}.
          </p>
        </CardContent>
      </Card>
    </aside>
  );
}

function SummaryRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex justify-between text-muted-foreground">
      <span>{label}</span>
      <span>{value}</span>
    </div>
  );
}

import { Star } from "lucide-react";
import { cn } from "@/lib/utils";

type SellerRatingInputProps = {
  value: number;
  onChange: (value: number) => void;
  disabled?: boolean;
};

export function SellerRatingInput({
  value,
  onChange,
  disabled,
}: SellerRatingInputProps) {
  return (
    <div className="flex items-center gap-1" role="radiogroup" aria-label="Nota do vendedor">
      {[1, 2, 3, 4, 5].map((rating) => (
        <button
          key={rating}
          type="button"
          disabled={disabled}
          onClick={() => onChange(rating)}
          className="rounded-full p-1 transition hover:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue disabled:cursor-not-allowed"
          aria-label={`${rating} estrela${rating > 1 ? "s" : ""}`}
          aria-checked={value === rating}
          role="radio"
        >
          <Star
            className={cn(
              "h-6 w-6 transition",
              rating <= value
                ? "fill-brand-orange text-brand-orange-ink"
                : "text-muted-foreground hover:text-brand-orange-ink",
            )}
          />
        </button>
      ))}
    </div>
  );
}

import { useRef, useState, type KeyboardEvent } from "react";
import { Link } from "react-router-dom";
import { ArrowRight, Footprints, UsersRound } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import type { ProductWithImages } from "@/types/product-detail";
import type { SharedPurchaseSide } from "@/types/shared-purchase";

interface SharedPurchaseOfferProps {
  product: ProductWithImages;
  onCreate: (side: SharedPurchaseSide) => boolean | Promise<boolean>;
}

const money = (value: number) =>
  value.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

const normalizeFootType = (footType?: string) =>
  String(footType || "")
    .trim()
    .toLocaleLowerCase("pt-BR");

export function SharedPurchaseOffer({
  product,
  onCreate,
}: SharedPurchaseOfferProps) {
  const [open, setOpen] = useState(false);
  const [side, setSide] = useState<SharedPurchaseSide>("left");
  const [creating, setCreating] = useState(false);
  const radioRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const normalizedFootType = normalizeFootType(product.foot_type);
  const isPair = ["pair", "par", "both", "par completo"].includes(normalizedFootType);

  if (!isPair) return null;

  const handleCreate = async () => {
    if (creating) return;
    setCreating(true);
    try {
      const created = await onCreate(side);
      if (created) setOpen(false);
    } finally {
      setCreating(false);
    }
  };

  const handleRadioKeyDown = (
    event: KeyboardEvent<HTMLButtonElement>,
    index: number,
  ) => {
    const sides: SharedPurchaseSide[] = ["left", "right"];
    let nextIndex: number | null = null;
    if (["ArrowRight", "ArrowDown"].includes(event.key)) {
      nextIndex = (index + 1) % sides.length;
    } else if (["ArrowLeft", "ArrowUp"].includes(event.key)) {
      nextIndex = (index - 1 + sides.length) % sides.length;
    } else if (event.key === "Home") {
      nextIndex = 0;
    } else if (event.key === "End") {
      nextIndex = sides.length - 1;
    }
    if (nextIndex === null) return;
    event.preventDefault();
    setSide(sides[nextIndex]);
    radioRefs.current[nextIndex]?.focus();
  };

  return (
    <section className="rounded-lg border border-border bg-slate-50 p-4">
      <div className="flex items-center gap-3">
        <span className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-white text-brand-blue-ink">
          <UsersRound className="h-4 w-4" />
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-xs font-bold uppercase tracking-[0.12em] text-brand-blue-ink">
            Compra compartilhada
          </p>
          <p className="mt-0.5 text-sm font-semibold text-foreground">
            Leve apenas um pé por{" "}
            <strong className="text-brand-blue-ink">{money(Number(product.price) / 2)}</strong>
          </p>
        </div>
      </div>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogTrigger asChild>
          <Button variant="outline" className="mt-3 min-h-11 w-full border-input bg-white text-brand-blue-ink hover:bg-brand-blue/5">
            Escolher meu pé
            <ArrowRight className="h-4 w-4" />
          </Button>
        </DialogTrigger>
        <DialogContent className="border-border sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>Qual pé você precisa?</DialogTitle>
            <DialogDescription>
              O outro lado ficará disponível no mural por até 48 horas.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-3 sm:grid-cols-2" role="radiogroup" aria-label="Pé desejado">
            {(["left", "right"] as SharedPurchaseSide[]).map((value, index) => {
              const selected = side === value;
              const label = value === "left" ? "Pé esquerdo" : "Pé direito";
              return (
                <button
                  ref={(element) => {
                    radioRefs.current[index] = element;
                  }}
                  key={value}
                  type="button"
                  role="radio"
                  aria-checked={selected}
                  tabIndex={selected ? 0 : -1}
                  onClick={() => setSide(value)}
                  onKeyDown={(event) => handleRadioKeyDown(event, index)}
                  className={`rounded-lg border p-4 text-left transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue ${
                    selected
                      ? "border-brand-blue bg-brand-blue/5 shadow-sm"
                      : "border-input hover:border-ring"
                  }`}
                >
                  <Footprints className={`h-5 w-5 ${selected ? "text-brand-blue-ink" : "text-muted-foreground"}`} />
                  <span className="mt-3 block font-bold text-foreground">{label}</span>
                  <span className="mt-1 block text-sm text-muted-foreground">
                    Tamanho {product.size || "informado no anúncio"}
                  </span>
                </button>
              );
            })}
          </div>

          <div className="rounded-lg border border-status-info/30 bg-status-info-soft p-4 text-sm leading-6 text-muted-foreground">
            Você ainda não será cobrado. A compra só avança depois que outra
            pessoa reservar o lado complementar.
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpen(false)} disabled={creating}>
              Cancelar
            </Button>
            <Button onClick={handleCreate} disabled={creating} aria-busy={creating} className="bg-brand-orange text-white hover:bg-brand-orange-hover">
              {creating ? "Publicando..." : "Publicar reserva"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Button asChild variant="link" className="mt-1 h-auto w-full py-1 text-xs text-brand-blue-ink hover:text-brand-blue-ink">
        <Link to={`/shared-purchases?product=${product.id}`}>
          Ver quem já procura este modelo
        </Link>
      </Button>
    </section>
  );
}

import { Minus, Plus } from "lucide-react";

interface ProductQuantitySelectorProps {
  maxQuantity: number;
  productName: string;
  selectedQuantity: number;
  onUpdateQuantity: (quantity: number) => void;
}

export function ProductQuantitySelector({
  maxQuantity,
  productName,
  selectedQuantity,
  onUpdateQuantity,
}: ProductQuantitySelectorProps) {
  return (
    <div className="mb-5 flex flex-wrap items-center justify-between gap-4">
      <div>
        <h2 className="mb-0 text-sm font-bold text-brand-dark">Quantidade</h2>
        <p className="mb-0 text-xs text-muted-foreground">
          Até {maxQuantity} por compra
        </p>
      </div>
      <div
        className="flex h-11 shrink-0 items-center rounded-md border border-input bg-white"
        role="group"
        aria-label={`Quantidade selecionada: ${selectedQuantity}`}
      >
        <button
          type="button"
          className="flex h-full w-11 items-center justify-center text-muted-foreground transition-colors hover:text-brand-blue-ink disabled:cursor-not-allowed disabled:text-gray-300"
          onClick={() => onUpdateQuantity(selectedQuantity - 1)}
          disabled={selectedQuantity <= 1}
          aria-label={`Diminuir quantidade de ${productName}`}
        >
          <Minus className="h-4 w-4" />
        </button>
        <output
          className="min-w-9 text-center text-sm font-bold text-brand-dark"
          aria-live="polite"
          aria-atomic="true"
        >
          {selectedQuantity}
        </output>
