import { registrationFieldProps } from "@/lib/registrationA11y";
import { CalendarDays, IdCard, User } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import type {
  CustomerInputChangeHandler,
  CustomerRegistrationForm,
} from "./types";
import { CustomerFormSectionHeader } from "./CustomerFormSectionHeader";

interface CustomerIdentitySectionProps {
  fieldErrors?: Record<string, string>;
  form: CustomerRegistrationForm;
  onChange: CustomerInputChangeHandler;
  onGenderChange: (value: string) => void;
}

export function CustomerIdentitySection({
  fieldErrors = {},
  form,
  onChange,
  onGenderChange,
}: CustomerIdentitySectionProps) {
  return (
    <section
      role="group"
      aria-labelledby="customer-identity-title"
      className="space-y-5"
    >
      <CustomerFormSectionHeader
        id="customer-identity-title"
        icon={User}
        title="Dados do comprador"
        description="Identificação e informações de perfil."
        toneClassName="bg-brand-blue/10 text-brand-blue-ink"
      />

      <div className="grid gap-5 sm:grid-cols-2">
        <div className="space-y-2 sm:col-span-2">
          <Label
            htmlFor="name"
            className="text-sm font-semibold text-muted-foreground"
          >
            Nome completo
          </Label>
          <div className="relative">
            <User
              aria-hidden="true"
              className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
            />
            <Input
              id="name"
              type="text"
              placeholder="Digite seu nome completo"
              className="pl-10 text-base"
              required
              value={form.name}
              onChange={onChange}
              {...registrationFieldProps("name", fieldErrors)}
              autoComplete="name"
            />
          </div>
        </div>

        <div className="space-y-2">
          <Label
            htmlFor="cpf"
            className="text-sm font-semibold text-muted-foreground"
          >
            <abbr title="Cadastro de Pessoas Físicas">CPF</abbr>{" "}
            <span className="font-normal">(opcional)</span>
          </Label>
          <div className="relative">
            <IdCard
              aria-hidden="true"
              className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
            />
            <Input
              id="cpf"
              type="text"
              placeholder="000.000.000-00"
              className="pl-10 text-base"
              pattern="[0-9.\-\s]*"
              minLength={11}
              maxLength={14}
              value={form.cpf}
              onChange={onChange}
              {...registrationFieldProps("cpf", fieldErrors, "cpf-help")}
              inputMode="numeric"
            />
          </div>
          <p
            id="cpf-help"
            className="text-sm text-muted-foreground sm:col-span-2"
          >
            Você pode informar seu CPF depois, no perfil ou ao finalizar uma
            compra real. Se preencher agora, use os 11 números, com ou sem
            pontuação.
          </p>
        </div>

        <div className="space-y-2">
          <Label
            htmlFor="birth_date"
            className="text-sm font-semibold text-muted-foreground"
