            Data de nascimento
          </Label>
          <div className="relative">
            <CalendarDays
              aria-hidden="true"
              className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
            />
            <Input
              id="birth_date"
              type="date"
              className="pl-10 text-base"
              required
              value={form.birth_date}
              onChange={onChange}
              {...registrationFieldProps("birth_date", fieldErrors)}
              autoComplete="bday"
            />
          </div>
        </div>

        <fieldset className="min-w-0 space-y-3 sm:col-span-2">
          <legend className="text-sm font-semibold text-muted-foreground">
            Gênero (opcional)
          </legend>
          <div className="grid gap-3 sm:grid-cols-3">
            <GenderOption
              id="masculino"
              label="Masculino"
              checked={form.gender === "masculino"}
              onChange={() => onGenderChange("masculino")}
            />
            <GenderOption
              id="feminino"
              label="Feminino"
              checked={form.gender === "feminino"}
              onChange={() => onGenderChange("feminino")}
            />
            <GenderOption
              id="outro"
              label="Outro"
              checked={form.gender === "outro"}
              onChange={() => onGenderChange("outro")}
            />
          </div>
        </fieldset>
      </div>
    </section>
  );
}

interface GenderOptionProps {
  checked: boolean;
  onChange: () => void;
  id: string;
  label: string;
}

function GenderOption({ id, label, checked, onChange }: GenderOptionProps) {
  return (
    <div className="flex items-center gap-3 rounded-lg border border-input p-3">
      <input
        type="radio"
        name="gender"
        value={id}
        id={id}
        checked={checked}
        onChange={onChange}
        className="h-6 w-6 shrink-0 accent-brand-blue"
      />
      <Label
        htmlFor={id}
        className="flex min-h-11 min-w-11 cursor-pointer items-center text-sm font-medium"
      >
        {label}
      </Label>
