  );
}

import { registrationPasswordHelp } from "@/lib/registrationA11y";
import { useState } from "react";
import { Eye, EyeOff, LockKeyhole } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { describedBy } from "@/lib/formA11y";
import type {
  CustomerFieldErrors,
  CustomerInputChangeHandler,
  CustomerRegistrationForm,
} from "./types";
import { CustomerFormSectionHeader } from "./CustomerFormSectionHeader";

interface CustomerSecuritySectionProps {
  fieldErrors: CustomerFieldErrors;
  form: CustomerRegistrationForm;
  formError: string | null;
  onChange: CustomerInputChangeHandler;
}

export function CustomerSecuritySection({
  fieldErrors,
  form,
  formError,
  onChange,
}: CustomerSecuritySectionProps) {
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  return (
    <section role="group" aria-labelledby="customer-security-title" className="space-y-5">
      <CustomerFormSectionHeader
        id="customer-security-title"
        icon={LockKeyhole}
        title="Segurança da conta"
        description="Defina a senha usada para entrar na Inclusivo."
        toneClassName="bg-slate-900/10 text-foreground"
      />

      <p id="register-password-help" className="text-sm text-muted-foreground">{registrationPasswordHelp}</p>
      <div className="grid gap-5 sm:grid-cols-2">
        <PasswordField
          id="password"
          label="Senha"
          placeholder="Digite sua senha"
          value={form.password}
          visible={showPassword}
          error={fieldErrors.password}
          formError={formError}
          onChange={onChange}
          onToggleVisible={() => setShowPassword((visible) => !visible)}
        />
        <PasswordField
          id="confirmPassword"
          label="Confirmar senha"
          placeholder="Confirme sua senha"
          value={form.confirmPassword}
          visible={showConfirmPassword}
          error={fieldErrors.confirmPassword}
          formError={formError}
          onChange={onChange}
          onToggleVisible={() =>
            setShowConfirmPassword((visible) => !visible)
          }
        />
      </div>
    </section>
  );
}

interface PasswordFieldProps {
  error?: string;
  formError: string | null;
  id: "password" | "confirmPassword";
  label: string;
  onChange: CustomerInputChangeHandler;
  onToggleVisible: () => void;
  placeholder: string;
  value: string;
  visible: boolean;
}

function PasswordField({
  error,
  formError,
  id,
  label,
  onChange,
  onToggleVisible,
  placeholder,
  value,
  visible,
}: PasswordFieldProps) {
  const errorId = `${id}-error`;
  const visibleLabel =
    id === "confirmPassword"
      ? visible
        ? "Ocultar confirmação de senha"
        : "Mostrar confirmação de senha"
      : visible
        ? "Ocultar senha"
        : "Mostrar senha";

  return (
    <div className="space-y-2">
      <Label htmlFor={id} className="text-sm font-semibold text-muted-foreground">
        {label}
      </Label>
      <div className="relative">
        <Input
          id={id}
          type={visible ? "text" : "password"}
          placeholder={placeholder}
          className="pr-12 text-base"
          required
          autoComplete="new-password"
          value={value}
          onChange={onChange}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy(
          "register-password-help",
          error && errorId,
          formError && "register-form-error",
          )}
        />
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="absolute right-0.5 top-1/2 h-11 w-11 -translate-y-1/2 p-0 text-muted-foreground hover:text-foreground"
          onClick={onToggleVisible}
          aria-label={visibleLabel}
          aria-pressed={visible}
          aria-controls={id}
        >
          {visible ? (
            <EyeOff className="h-5 w-5" aria-hidden />
          ) : (
            <Eye className="h-5 w-5" aria-hidden />
          )}
        </Button>
      </div>
      {error && (
        <p id={errorId} role="alert" className="text-sm text-status-danger">
          {error}
        </p>
      )}
    </div>
  );
}

import type React from "react";
import { Link } from "react-router-dom";
import { ShieldCheck } from "lucide-react";

import { Label } from "@/components/ui/label";
import { describedBy } from "@/lib/formA11y";
import type {
  CustomerCheckboxChangeHandler,
  CustomerFieldErrors,
  CustomerRegistrationForm,
} from "./types";
import { CustomerFormSectionHeader } from "./CustomerFormSectionHeader";

interface CustomerTermsSectionProps {
  fieldErrors: CustomerFieldErrors;
