  sellerId: number | null;
  updatingOrderId: number | null;
  updatingRequestId: number | null;
  onAdvanceOrder: (order: SellerOrder) => void;
  onUpdateRequestStatus: (
    requestId: number,
    status: PostPurchaseRequestStatus,
    sellerResponse?: string,
  ) => void;
}

export function SellerOrdersList({
  loading,
