import { LoadingState } from "@/components/ui/LoadingState";
import { MapPin, Home, Building, Star } from "lucide-react";
import type { KeyboardEvent } from "react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import type { Address } from "@/types/address";

type ShippingAddressCardProps = {
  loading: boolean;
  addresses: Address[];
  selectedAddress: number | null;
  onSelectAddress: (addressId: number) => void;
  onAddAddress: () => void;
};

export default function ShippingAddressCard({
  loading,
  addresses,
  selectedAddress,
  onSelectAddress,
  onAddAddress,
}: ShippingAddressCardProps) {
  const addressIds = addresses.map((address) => address.id);
  const tabStopId = addressIds.includes(selectedAddress ?? -1)
    ? selectedAddress
    : addressIds[0];

  const handleAddressKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const keys = [
      "ArrowDown",
      "ArrowRight",
      "ArrowUp",
      "ArrowLeft",
      "Home",
      "End",
    ];
    if (!keys.includes(event.key) || addressIds.length === 0) return;

    event.preventDefault();
    const currentIndex = Math.max(
      0,
      addressIds.indexOf(selectedAddress ?? addressIds[0]),
    );
    const lastIndex = addressIds.length - 1;
    const nextIndex =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? lastIndex
          : event.key === "ArrowDown" || event.key === "ArrowRight"
            ? Math.min(lastIndex, currentIndex + 1)
            : Math.max(0, currentIndex - 1);

    const nextAddressId = addressIds[nextIndex];
    onSelectAddress(nextAddressId);
    requestAnimationFrame(() => {
      document
        .querySelector<HTMLButtonElement>(
          `[data-shipping-address-id="${nextAddressId}"]`,
        )
        ?.focus();
    });
  };

  const getAddressIcon = (type: string) => {
    switch (type) {
      case "home":
        return <Home className="h-5 w-5 text-brand-blue-ink" />;
      case "work":
        return <Building className="h-5 w-5 text-brand-blue-ink" />;
      default:
        return <MapPin className="h-5 w-5 text-brand-blue-ink" />;
    }
  };

  const getTypeLabel = (type: string) => {
    switch (type) {
      case "home":
        return "Casa";
      case "work":
        return "Trabalho";
      default:
        return "outro";
    }
  };

  return (
    <Card className="overflow-hidden rounded-lg border-border bg-white shadow-sm">
      <div className="h-1.5 bg-gradient-to-r from-brand-blue to-brand-orange" />
      <CardHeader className="border-b border-border">
        <h2 className="flex items-center gap-2 text-2xl font-semibold text-brand-dark">
          <MapPin className="h-6 w-6 text-brand-blue-ink" />
          Endereço de entrega
        </h2>
      </CardHeader>
      <CardContent className="space-y-4">
        {loading ? (
          <LoadingState variant="compact" label="Carregando endereços..." />
        ) : addresses.length === 0 ? (
          <div className="space-y-4 text-center">
            <p className="text-muted-foreground">
              Você ainda não possui endereços cadastrados...
            </p>
            <Button
              className="bg-brand-orange font-semibold text-white hover:bg-brand-orange-hover"
              onClick={onAddAddress}
            >
              Adicionar novo endereço
            </Button>
          </div>
        ) : (
          <div
            className="space-y-3"
            role="radiogroup"
            tabIndex={-1}
            aria-label="Escolha o endereço de entrega"
            onKeyDown={handleAddressKeyDown}
          >
            {addresses.map((address) => (
              <button
                key={address.id}
                type="button"
                role="radio"
                tabIndex={address.id === tabStopId ? 0 : -1}
                data-shipping-address-id={address.id}
                aria-checked={selectedAddress === address.id}
                onClick={() => onSelectAddress(address.id)}
                className={`w-full p-4 rounded-lg border-2 text-left cursor-pointer transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-blue focus-visible:ring-offset-2 ${
                  selectedAddress === address.id
                    ? "border-brand-blue bg-brand-blue/5 shadow-md"
                    : "border-input hover:border-ring hover:bg-slate-50"
                }`}
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-center gap-3">
                    {getAddressIcon(address.address_type)}
                    <div className="flex items-center gap-2">
                      <span className="flex items-center">
                        <span className="font-semibold text-lg m-0 p-0 leading-tight">
                          {address.recipient_name}
                        </span>
                      </span>
                      <span className="flex items-center">
                        <Badge
                          variant={
                            address.address_type === "home"
                              ? "default"
                              : "secondary"
                          }
                          className="ml-1 px-2 py-0.5 text-xs flex items-center"
                        >
                          {getTypeLabel(address.address_type)}
                        </Badge>
                      </span>
                    </div>
                  </div>
                  {address.is_primary && (
                    <Badge className="bg-status-success-soft text-status-success border-status-success/30">
                      <Star className="h-3 w-3 mr-1" />
                      Padrão
                    </Badge>
                  )}
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-1 text-sm mt-2">
                  <div>
                    <span className="font-medium">
                      {address.street}, {address.number}
                    </span>
                    {address.complement && (
                      <span className="text-muted-foreground">
                        {" "}
                        - {address.complement}
                      </span>
                    )}
                    <div className="text-muted-foreground">
                      {address.district}, {address.city} - {address.state}
                    </div>
                  </div>
                  <div className="flex flex-col sm:items-end">
                    <span className="font-mono text-base font-semibold text-brand-blue-ink">
                      CEP: {address.zip_code}
                    </span>
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

