};

type ShippingMethodCardProps = {
  aggregatedOptions: AggregatedOption[];
  fallbackOptions: FallbackOption[];
  selectedShipping: string;
  onSelectShipping: (optionId: string) => void;
  shippingErrors: string[];
};

export default function ShippingMethodCard({
  aggregatedOptions,
  fallbackOptions,
  selectedShipping,
  onSelectShipping,
  shippingErrors,
}: ShippingMethodCardProps) {
  const visibleOptionIds =
    aggregatedOptions.length > 0
      ? aggregatedOptions.map((option) => option.id)
      : fallbackOptions.map((option) => option.id);

  const tabStopId = visibleOptionIds.includes(selectedShipping)
    ? selectedShipping
    : visibleOptionIds[0];

  const handleShippingKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const keys = [
      "ArrowDown",
      "ArrowRight",
      "ArrowUp",
      "ArrowLeft",
      "Home",
      "End",
    ];
    if (!keys.includes(event.key) || visibleOptionIds.length === 0) return;

    event.preventDefault();
    const currentIndex = Math.max(
      0,
      visibleOptionIds.indexOf(selectedShipping),
    );
    const lastIndex = visibleOptionIds.length - 1;
    const nextIndex =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? lastIndex
          : event.key === "ArrowDown" || event.key === "ArrowRight"
            ? Math.min(lastIndex, currentIndex + 1)
            : Math.max(0, currentIndex - 1);

    const nextOptionId = visibleOptionIds[nextIndex];
    onSelectShipping(nextOptionId);
    requestAnimationFrame(() => {
      document
        .querySelector<HTMLButtonElement>(
          `[data-shipping-option-id="${nextOptionId}"]`,
        )
        ?.focus();
    });
  };

  return (
    <Card className="overflow-hidden rounded-lg border-border bg-white shadow-sm">
      <div className="h-1.5 bg-gradient-to-r from-brand-orange to-brand-blue" />
      <CardHeader className="border-b border-border">
        <h2 className="flex items-center gap-2 text-2xl font-semibold text-brand-dark">
          <Truck className="h-6 w-6 text-brand-orange-ink" />
          Método de entrega
        </h2>
      </CardHeader>
      <CardContent className="space-y-4">
        {aggregatedOptions.length > 0 ? (
          <div
            className="space-y-3"
            role="radiogroup"
            tabIndex={-1}
            aria-label="Escolha o método de entrega"
            onKeyDown={handleShippingKeyDown}
          >
            {shippingErrors && shippingErrors.length > 0 && (
              <div className="bg-status-warning-soft border-l-4 border-status-warning/30 p-3 rounded mb-2">
                <div className="font-semibold text-status-warning">
                  Problemas encontrados ao calcular frete:
                </div>
                <ul className="text-sm text-status-warning list-disc ml-5">
                  {shippingErrors.map((err, i) => (
                    <li key={i}>{err}</li>
                  ))}
                </ul>
              </div>
            )}
            {aggregatedOptions.map((opt) => (
              <button
                key={opt.id}
                type="button"
                role="radio"
                aria-label={opt.name}
                tabIndex={opt.id === tabStopId ? 0 : -1}
                data-shipping-option-id={opt.id}
                aria-checked={selectedShipping === opt.id}
                onClick={() => {
                  onSelectShipping(opt.id);
                }}
                className={`w-full p-4 rounded-lg border-2 text-left cursor-pointer transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-orange focus-visible:ring-offset-2 ${
                  selectedShipping === opt.id
                    ? "border-brand-orange bg-brand-orange/5 shadow-md"
                    : "border-input hover:border-ring hover:bg-slate-50"
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="pr-4">
                    <span className="block font-semibold">{opt.name}</span>
                    <p className="text-sm text-muted-foreground">
                      {opt.description || "Frete calculado com base na rota."}
                    </p>
                    <p className="text-sm font-medium text-brand-orange-ink">
                      {opt.days}
                      {opt.estimatedDateMin && opt.estimatedDateMax
                        ? ` · ${formatDeliveryWindow(opt.estimatedDateMin, opt.estimatedDateMax)}`
                        : ""}
                    </p>
                    {(opt.carrier || opt.distanceKm) && (
                      <p className="mt-1 text-xs text-muted-foreground">
                        {opt.carrier || "Parceiro logístico"}
                        {opt.distanceKm
                          ? ` · rota estimada de ${Math.round(opt.distanceKm)} km`
                          : ""}
                      </p>
                    )}
                    {opt.estimateBasis && (
                      <p className="mt-1 text-xs text-muted-foreground">
                        Prazo calculado por {opt.estimateBasis}.
                      </p>
                    )}
                  </div>
                  <div className="text-lg font-bold">
                    R$ {opt.price.toFixed(2)}
                  </div>
                </div>
              </button>
            ))}
          </div>
        ) : (
          <div
            className="space-y-3"
            role="radiogroup"
            tabIndex={-1}
            aria-label="Escolha o método de entrega"
            onKeyDown={handleShippingKeyDown}
          >
            {fallbackOptions.map((option) => (
              <button
                key={option.id}
                type="button"
                role="radio"
                aria-label={option.name}
                tabIndex={option.id === tabStopId ? 0 : -1}
                data-shipping-option-id={option.id}
                aria-checked={selectedShipping === option.id}
                onClick={() => {
                  onSelectShipping(option.id);
                }}
                className={`w-full p-4 rounded-lg border-2 text-left cursor-pointer transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-orange focus-visible:ring-offset-2 ${
                  selectedShipping === option.id
                    ? "border-brand-orange bg-brand-orange/5 shadow-md"
                    : "border-input hover:border-ring hover:bg-slate-50"
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="rounded-lg bg-brand-orange/10 p-2">
                      {option.icon}
                    </div>
                    <div>
                      <span className="block font-semibold">{option.name}</span>
                      <p className="text-sm text-muted-foreground">
                        {option.description}
                      </p>
                      <p className="text-sm font-medium text-brand-orange-ink">
                        {option.estimatedDays}
                      </p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-lg font-bold">
                      R$ {option.price.toFixed(2)}
                    </p>
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function formatDeliveryWindow(start: string, end: string) {
  const formatter = new Intl.DateTimeFormat("pt-BR", {
    day: "2-digit",
    month: "short",
  });
  return `chega entre ${formatter.format(new Date(start))} e ${formatter.format(
    new Date(end),
  )}`;
}

