import { RouteSkeletonContent } from "./RouteSkeletonContent";
import { useInRouterContext } from "react-router-dom";
import { Skeleton } from "./skeleton";
import { cn } from "@/lib/utils";

type LoadingStateProps = {
  label?: string;
  description?: string;
  variant?: "page" | "section" | "compact";
  className?: string;
};

/** Keep surrounding controls usable while only the pending content is replaced. */
export function LoadingState({
  label = "Carregando...",
  description,
  variant = "section",
  className,
}: LoadingStateProps) {
  const inRouter = useInRouterContext();
  const routeLayout = variant === "page" && inRouter;
  const Tag = variant === "page" ? "main" : "div";
  return (
    <Tag
      id={variant === "page" ? "main-content" : undefined}
      data-page-loading={variant === "page" ? "true" : undefined}
      tabIndex={variant === "page" ? -1 : undefined}
      className={cn(
        "w-full min-w-0",
        variant === "page" && "min-h-[65vh] flex-1",
        variant === "section" && "py-6",
        variant === "compact" && "py-3",
        className,
      )}
    >
      <div
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      >
        <p className="m-0 font-semibold leading-relaxed">{label}</p>
        {description && (
          <p className="mb-0 mt-2 text-sm leading-relaxed text-muted-foreground">
            {description}
          </p>
        )}
      </div>
      <div aria-hidden="true" className="w-full space-y-4">
        {routeLayout ? (
          <RouteSkeletonContent />
        ) : variant === "compact" ? (
          <div className="space-y-2">
            <Skeleton className="h-3 w-3/4" />
            <Skeleton className="h-3 w-1/2" />
          </div>
        ) : (
          <div className="divide-y divide-border rounded-lg border border-border px-4">
            {[0, 1, 2].map((row) => (
              <div key={row} className="space-y-2 py-4">
                <Skeleton className="h-4 w-2/3 max-w-lg" />
                <Skeleton className="h-3 w-1/3 max-w-xs" />
              </div>
            ))}
          </div>
        )}
      </div>
    </Tag>
  );
}

