import { X } from "lucide-react";

import { cn } from "@/lib/utils";

const ToastProvider = ToastPrimitives.Provider;

const ToastViewport = React.forwardRef<
  React.ElementRef<typeof ToastPrimitives.Viewport>,
  React.ComponentPropsWithoutRef<typeof ToastPrimitives.Viewport>
>(({ className, ...props }, ref) => (
  <ToastPrimitives.Viewport
    ref={ref}
    aria-label="Mensagens de status"
    className={cn(
      "fixed top-0 z-[100] flex max-h-[100dvh] w-full max-w-[100vw] flex-col-reverse overflow-x-hidden p-4 sm:bottom-0 sm:right-0 sm:top-auto sm:flex-col md:max-w-[420px]",
      className,
    )}
    {...props}
  />
));
ToastViewport.displayName = ToastPrimitives.Viewport.displayName;

const toastVariants = cva(
  "group pointer-events-auto relative flex w-full min-w-0 flex-wrap items-center justify-between gap-2 overflow-hidden rounded-md border p-4 pr-8 shadow-lg transition-all data-[swipe=cancel]:translate-x-0 data-[swipe=end]:translate-x-[var(--radix-toast-swipe-end-x)] data-[swipe=move]:translate-x-[var(--radix-toast-swipe-move-x)] data-[swipe=move]:transition-none data-[state=open]:animate-in data-[state=closed]:animate-out data-[swipe=end]:animate-out data-[state=closed]:fade-out-80 data-[state=closed]:slide-out-to-right-full data-[state=open]:slide-in-from-top-full data-[state=open]:sm:slide-in-from-bottom-full",
  {
    variants: {
      variant: {
        default: "border bg-background text-foreground",
        destructive:
          "destructive group border-destructive bg-destructive text-destructive-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

const Toast = React.forwardRef<
  React.ElementRef<typeof ToastPrimitives.Root>,
  React.ComponentPropsWithoutRef<typeof ToastPrimitives.Root> &
    VariantProps<typeof toastVariants>
>(({ className, variant, ...props }, ref) => {
  return (
    <ToastPrimitives.Root
      ref={ref}
      // O anúncio é feito por ToastAnnounce do Radix; o cartão mantém a
      // semântica de item da lista que compõe ToastViewport.
      role="listitem"
      className={cn(toastVariants({ variant }), className)}
      {...props}
    />
  );
});
Toast.displayName = ToastPrimitives.Root.displayName;

const ToastAction = React.forwardRef<
  React.ElementRef<typeof ToastPrimitives.Action>,
  React.ComponentPropsWithoutRef<typeof ToastPrimitives.Action>
>(({ className, ...props }, ref) => (
  <ToastPrimitives.Action
    ref={ref}
    className={cn(
      "inline-flex min-h-10 w-full max-w-full shrink-0 items-center justify-center rounded-md border bg-transparent px-3 text-sm font-medium ring-offset-background transition-colors hover:bg-secondary hover:text-secondary-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 sm:min-h-8 sm:w-auto group-[.destructive]:border-white group-[.destructive]:hover:border-white group-[.destructive]:hover:bg-destructive group-[.destructive]:hover:text-destructive-foreground group-[.destructive]:focus:ring-destructive",
      className,
    )}
    {...props}
  />
));
ToastAction.displayName = ToastPrimitives.Action.displayName;

const ToastClose = React.forwardRef<
  React.ElementRef<typeof ToastPrimitives.Close>,
  React.ComponentPropsWithoutRef<typeof ToastPrimitives.Close>
>(({ className, ...props }, ref) => (
  <ToastPrimitives.Close
    ref={ref}
    className={cn(
      "absolute right-2 top-2 rounded-md p-1 text-foreground opacity-100 transition-opacity hover:text-foreground focus:outline-none focus:ring-2 group-[.destructive]:text-destructive-foreground group-[.destructive]:hover:text-white group-[.destructive]:focus:ring-white group-[.destructive]:focus:ring-offset-destructive",
      className,
    )}
    aria-label="Fechar mensagem"
    toast-close=""
    {...props}
  >
    <X className="h-4 w-4" />
  </ToastPrimitives.Close>
));
ToastClose.displayName = ToastPrimitives.Close.displayName;

const ToastTitle = React.forwardRef<
  React.ElementRef<typeof ToastPrimitives.Title>,
  React.ComponentPropsWithoutRef<typeof ToastPrimitives.Title>
>(({ className, ...props }, ref) => (
  <ToastPrimitives.Title
    ref={ref}
    className={cn("text-sm font-semibold", className)}
    {...props}
  />
));
ToastTitle.displayName = ToastPrimitives.Title.displayName;

const ToastDescription = React.forwardRef<
  React.ElementRef<typeof ToastPrimitives.Description>,
  React.ComponentPropsWithoutRef<typeof ToastPrimitives.Description>
>(({ className, ...props }, ref) => (
  <ToastPrimitives.Description
    ref={ref}
    className={cn("text-sm", className)}
    {...props}
  />
));
ToastDescription.displayName = ToastPrimitives.Description.displayName;

type ToastProps = React.ComponentPropsWithoutRef<typeof Toast>;

type ToastActionElement = React.ReactElement<typeof ToastAction>;

export {
  type ToastProps,
  type ToastActionElement,
  ToastProvider,
  ToastViewport,
  Toast,
  ToastTitle,
  ToastDescription,
  ToastClose,
  ToastAction,
};

import { OperationErrorNotice } from "@/components/ui/OperationErrorNotice";
import { useState } from "react";
import { useCatalogAccessibility } from "@/hooks/accessibility/useCatalogAccessibility";
import { RefreshCw } from "lucide-react";
import { Footer } from "@/components/layout/Footer";
import { Navbar } from "@/components/layout/Navbar";
import SkipLink from "@/components/ui/SkipLink";
import { SharedPurchaseJoinDialog } from "@/components/shared-purchase/SharedPurchaseJoinDialog";
import { SharedPurchasesHero } from "@/components/shared-purchase/SharedPurchasesHero";
import { SharedPurchasesHowItWorks } from "@/components/shared-purchase/SharedPurchasesHowItWorks";
import { SharedPurchasesListSection } from "@/components/shared-purchase/SharedPurchasesListSection";
import { useSharedPurchases } from "@/hooks/shared-purchases/useSharedPurchases";

export default function SharedPurchases() {
  useCatalogAccessibility();
  const [showCountdown, setShowCountdown] = useState(true);
  const shared = useSharedPurchases();
  const clearFilters = () => {
    shared.clearFilters();
    document.getElementById("shared-search")?.focus();
  };
  return (
    <div className="shared-purchase-page flex min-h-screen flex-col bg-slate-50">
      <SkipLink />
      <Navbar />
      <main id="main-content" tabIndex={-1} className="flex-1">
        <SharedPurchasesHero
          demonstration={shared.showExamples}
          matchedCount={shared.matchedCount}
          waitingCount={shared.waitingCount}
        />
        <div className="container mx-auto max-w-6xl px-4 py-8 sm:px-6 sm:py-10">
          <SharedPurchasesHowItWorks />
          <div className="mb-6 flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
            <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
              <button
                type="button"
                disabled={shared.loading}
                onClick={shared.refresh}
                aria-busy={shared.loading}
                className="inline-flex min-h-11 items-center gap-2 rounded-md border border-input bg-white px-4 font-semibold text-brand-blue-ink disabled:opacity-60"
              >
                <RefreshCw
                  aria-hidden
                  className={`h-4 w-4 ${shared.loading ? "animate-spin motion-reduce:animate-none" : ""}`}
                />
                {shared.loading
                  ? "Atualizando reservas…"
                  : "Atualizar reservas"}
              </button>
              {shared.lastUpdated && !shared.showExamples && (
                <p className="text-sm text-muted-foreground">
                  Atualizado às{" "}
                  <time dateTime={shared.lastUpdated.toISOString()}>
                    {shared.lastUpdated.toLocaleTimeString("pt-BR", {
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </time>
                </p>
              )}
            </div>
            <button
              type="button"
              aria-pressed={!showCountdown}
              onClick={() => setShowCountdown((visible) => !visible)}
              className="min-h-11 rounded-md px-1 text-sm font-semibold text-brand-blue-ink underline underline-offset-4"
            >
              {showCountdown
                ? "Ocultar contagem regressiva"
                : "Mostrar contagem regressiva"}
            </button>
            <button
              type="button"
              disabled={shared.loading}
              onClick={shared.toggleExamples}
              aria-pressed={shared.showExamples}
              className="min-h-11 rounded-md px-1 text-sm font-semibold text-brand-blue-ink underline underline-offset-4 disabled:opacity-60"
            >
              {shared.showExamples
                ? "Ver reservas reais"
                : "Ver exemplos de reservas"}
            </button>
          </div>
          {shared.showExamples && (
            <div
              role="status"
              className="mb-6 rounded-lg border border-status-info/30 bg-status-info-soft p-4 text-foreground"
            >
              <p className="font-semibold">Reservas de demonstração</p>
              <p className="mt-2 text-base leading-relaxed">
                Pessoas, tamanhos e valores fictícios para conhecer o fluxo.
                Você pode simular o encontro de um par; nenhum pedido ou
                pagamento será criado.
              </p>
            </div>
          )}
          {shared.error && !shared.showExamples && (
            <div
              role="alert"
              className="mb-6 rounded-lg border border-status-danger/30 bg-white p-5 text-status-danger"
            >
              <p>{shared.error}</p>
              <button
                type="button"
                onClick={shared.refresh}
                className="mt-2 min-h-11 font-semibold underline"
              >
                Tentar novamente
              </button>
            </div>
          )}
          {!shared.selected && <OperationErrorNotice error={shared.operationError} />}
          <SharedPurchasesListSection
            showCountdown={showCountdown}
            highlightedId={shared.highlightedId}
            loading={shared.loading}
            error={Boolean(shared.error) && !shared.showExamples}
            query={shared.query}
            sideFilter={shared.sideFilter}
            availableSizes={shared.availableSizes}
            sizeFilter={shared.sizeFilter}
            sortBy={shared.sortBy}
            onlyAvailable={shared.onlyAvailable}
            hasFilters={shared.hasFilters}
            reservations={shared.visibleReservations}
            userName={shared.user?.name}
            userId={shared.user?.id ? Number(shared.user.id) : undefined}
            onJoin={shared.requestJoin}
            onPay={shared.paySharedReservation}
            onQueryChange={shared.setQuery}
            onSideFilterChange={shared.setSideFilter}
            onSizeChange={shared.setSizeFilter}
            onSortChange={shared.setSortBy}
            onAvailableChange={shared.setOnlyAvailable}
            onClear={clearFilters}
          />
        </div>
      </main>
      <SharedPurchaseJoinDialog
        selected={shared.selected}
        error={shared.operationError}
        onClose={() => shared.setSelected(null)}
        onConfirm={shared.confirmJoin}
        busy={shared.joining}
      />
      <Footer />
    </div>
  );
}

import { type KeyboardEvent, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { ChevronLeft, ArrowRight } from "lucide-react";
import { useFocusReturnOnClose } from "@/hooks/accessibility/useFocusReturnOnClose";

interface FootSelectionModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelect: (foot: "left" | "right") => void;
  onBack: () => void;
}

export const FootSelectionModal = ({
  open,
  onOpenChange,
  onSelect,
  onBack,
}: FootSelectionModalProps) => {
  useFocusReturnOnClose(open);
  const [selectedFoot, setSelectedFoot] = useState<"left" | "right" | null>(
    null,
  );
  const leftButtonRef = useRef<HTMLButtonElement>(null);
  const rightButtonRef = useRef<HTMLButtonElement>(null);

  const navigate = useNavigate();

  const selectFoot = (foot: "left" | "right") => {
    setSelectedFoot(foot);
    requestAnimationFrame(() => {
      if (foot === "left") leftButtonRef.current?.focus();
      else rightButtonRef.current?.focus();
    });
  };

  const handleRadioKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const keys = [
      "ArrowDown",
      "ArrowRight",
      "ArrowUp",
      "ArrowLeft",
      "Home",
      "End",
    ];
    if (!keys.includes(event.key)) return;

    event.preventDefault();
    if (event.key === "Home") {
      selectFoot("left");
      return;
    }
    if (event.key === "End") {
      selectFoot("right");
      return;
    }

    selectFoot(selectedFoot === "left" ? "right" : "left");
  };

  const handleConfirm = () => {
    if (selectedFoot) {
      onSelect(selectedFoot);
      onOpenChange(false);
      setSelectedFoot(null);
    }
  };

  const handleCancel = () => {
    navigate("/seller/dashboard");
  };

  const handleBack = () => {
    onBack();
    setSelectedFoot(null);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Seleção do pé</DialogTitle>
          <DialogDescription>
            Escolha se você deseja cadastrar um pé direito ou esquerdo
          </DialogDescription>
        </DialogHeader>

        <div
          className="mt-4 grid grid-cols-1 gap-4"
          role="radiogroup"
          aria-label="Pé do produto"
          tabIndex={-1}
          onKeyDown={handleRadioKeyDown}
        >
          <button
            ref={leftButtonRef}
            type="button"
            role="radio"
            aria-label="Pé esquerdo"
            aria-checked={selectedFoot === "left"}
            tabIndex={selectedFoot === null || selectedFoot === "left" ? 0 : -1}
            className="rounded-lg text-left focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-brand-blue focus-visible:ring-offset-2"
            onClick={() => setSelectedFoot("left")}
          >
            <Card
              className={`cursor-pointer transition-all ${
                selectedFoot === "left"
                  ? "ring-2 ring-blue-500 bg-status-info-soft"
                  : "hover:bg-gray-50"
              }`}
            >
              <CardContent className="p-card text-center">
                <div className="h-12 w-12 mx-auto mb-3 bg-status-info-soft rounded-full flex items-center justify-center">
                  <span className="text-2xl">🦶</span>
                </div>
                <h3 className="font-semibold text-lg mb-2">Pé esquerdo</h3>
                <p className="text-muted-foreground text-sm">
                  Calçado para o pé esquerdo
                </p>
              </CardContent>
            </Card>
          </button>

          <button
            ref={rightButtonRef}
            type="button"
            role="radio"
            aria-label="Pé direito"
            aria-checked={selectedFoot === "right"}
            tabIndex={selectedFoot === "right" ? 0 : -1}
            className="rounded-lg text-left focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-brand-blue focus-visible:ring-offset-2"
            onClick={() => setSelectedFoot("right")}
          >
            <Card
              className={`cursor-pointer transition-all ${
                selectedFoot === "right"
                  ? "ring-2 ring-blue-500 bg-status-info-soft"
                  : "hover:bg-gray-50"
              }`}
            >
              <CardContent className="p-card text-center">
                <div className="h-12 w-12 mx-auto mb-3 bg-status-success-soft rounded-full flex items-center justify-center">
                  <span className="text-2xl transform scale-x-[-1]">🦶</span>
                </div>
                <h3 className="font-semibold text-lg mb-2">Pé direito</h3>
                <p className="text-muted-foreground text-sm">
                  Calçado para o pé direito
                </p>
              </CardContent>
            </Card>
          </button>
        </div>

        <div className="flex gap-3 mt-6">
          <Button variant="outline" className="gap-2" onClick={handleBack}>
            <ChevronLeft className="h-4 w-4" />
            Voltar
          </Button>
          <Button variant="outline" className="flex-1" onClick={handleCancel}>
            Cancelar
          </Button>
          <Button
            className="flex-1 gap-2"
            onClick={handleConfirm}
            disabled={!selectedFoot}
          >
            Continuar
            <ArrowRight className="h-4 w-4" />
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default FootSelectionModal;

import { type KeyboardEvent, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Footprints, Users } from "lucide-react";
import { useFocusReturnOnClose } from "@/hooks/accessibility/useFocusReturnOnClose";

interface ProductTypeModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelect: (type: "single" | "pair") => void;
}

export const ProductTypeModal = ({
  open,
  onOpenChange,
  onSelect,
}: ProductTypeModalProps) => {
  useFocusReturnOnClose(open);
  const [selectedType, setSelectedType] = useState<"single" | "pair" | null>(
    null,
  );
  const singleButtonRef = useRef<HTMLButtonElement>(null);
  const pairButtonRef = useRef<HTMLButtonElement>(null);

  const navigate = useNavigate();

  const selectType = (type: "single" | "pair") => {
    setSelectedType(type);
    requestAnimationFrame(() => {
      if (type === "single") singleButtonRef.current?.focus();
      else pairButtonRef.current?.focus();
    });
  };

  const handleRadioKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const keys = [
      "ArrowDown",
      "ArrowRight",
      "ArrowUp",
      "ArrowLeft",
      "Home",
      "End",
    ];
    if (!keys.includes(event.key)) return;

    event.preventDefault();
    if (event.key === "Home") {
      selectType("single");
      return;
    }
    if (event.key === "End") {
      selectType("pair");
      return;
    }

    selectType(selectedType === "single" ? "pair" : "single");
  };

  const handleConfirm = () => {
    if (selectedType) {
      onSelect(selectedType);
      onOpenChange(false);
      setSelectedType(null);
    }
  };

  const handleCancel = () => {
    onOpenChange(false);
    setSelectedType(null);
    navigate("/seller/dashboard");
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Tipo de produto</DialogTitle>
          <DialogDescription>
            Escolha se você deseja cadastrar um pé único ou um par completo
          </DialogDescription>
        </DialogHeader>

        <div
          className="mt-4 grid grid-cols-1 gap-4"
          role="radiogroup"
          aria-label="Tipo de produto"
          tabIndex={-1}
          onKeyDown={handleRadioKeyDown}
        >
          <button
            ref={singleButtonRef}
            type="button"
            role="radio"
            aria-label="Pé único"
            aria-checked={selectedType === "single"}
            tabIndex={
              selectedType === null || selectedType === "single" ? 0 : -1
            }
            className="rounded-lg text-left focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-brand-blue focus-visible:ring-offset-2"
            onClick={() => setSelectedType("single")}
          >
            <Card
              className={`cursor-pointer transition-all ${
                selectedType === "single"
                  ? "ring-2 ring-blue-500 bg-status-info-soft"
                  : "hover:bg-gray-50"
              }`}
            >
              <CardContent className="p-card text-center">
                <Footprints className="h-12 w-12 mx-auto mb-3 text-status-info" />
                <h3 className="font-semibold text-lg mb-2">Pé único</h3>
                <p className="text-muted-foreground text-sm">
                  Ideal para pessoas que precisam de tamanhos diferentes para
                  cada pé
                </p>
              </CardContent>
            </Card>
          </button>

          <button
            ref={pairButtonRef}
            type="button"
            role="radio"
            aria-label="Par completo"
            aria-checked={selectedType === "pair"}
            tabIndex={selectedType === "pair" ? 0 : -1}
            className="rounded-lg text-left focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-brand-blue focus-visible:ring-offset-2"
            onClick={() => setSelectedType("pair")}
          >
            <Card
              className={`cursor-pointer transition-all ${
                selectedType === "pair"
                  ? "ring-2 ring-blue-500 bg-status-info-soft"
                  : "hover:bg-gray-50"
              }`}
            >
              <CardContent className="p-card text-center">
                <Users className="h-12 w-12 mx-auto mb-3 text-status-success" />
                <h3 className="font-semibold text-lg mb-2">Par completo</h3>
                <p className="text-muted-foreground text-sm">
                  Par tradicional com ambos os pés do mesmo tamanho
                </p>
              </CardContent>
            </Card>
          </button>
        </div>

        <div className="flex gap-3 mt-6">
          <Button variant="outline" className="flex-1" onClick={handleCancel}>
            Cancelar
          </Button>
          <Button
            className="flex-1"
            onClick={handleConfirm}
            disabled={!selectedType}
          >
            Continuar
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default ProductTypeModal;
